// Replace this with your own source: a Google Sheet, Airtable, a CSV, a broker export.
// One item per holding: symbol, quantity and (optionally) cost per share.
return [
  { json: { symbol: 'AAPL', quantity: 40, cost: 150.0 } },
  { json: { symbol: 'MSFT', quantity: 15, cost: 310.5 } },
  { json: { symbol: 'NVDA', quantity: 60, cost: 95.2 } },
  { json: { symbol: 'SAP.DE', quantity: 25, cost: 140 } },
];

const rows = $input.all().map(i => i.json);
const summary = rows.find(r => r.kind === 'summary');
const holdings = rows.filter(r => r.kind === 'holding');
const flagged = holdings.filter(r => (r.flags || []).length > 0);
const failed = holdings.filter(r => r.found === false || r.valid === false);

const lines = [];
if (summary.currency) {
  lines.push(`Portfolio ${summary.total_value} ${summary.currency}, today ${summary.day_change} (${summary.day_change_pct}%)`);
  if (summary.top_weight_symbol) lines.push(`Largest position: ${summary.top_weight_symbol} at ${summary.top_weight_pct}%`);
} else {
  for (const g of summary.by_currency) {
    lines.push(`${g.currency}: ${g.total_value}, today ${g.day_change} (${g.day_change_pct}%)`);
  }
}
for (const h of flagged) lines.push(`${h.symbol}: ${h.flags.join(', ')}`);
if (failed.length) lines.push('Not checked: ' + failed.map(h => `${h.symbol} (${h.error})`).join('; '));

return [{ json: { message: lines.join('\n'), flagged: flagged.length } }];
